package oracle;
import java.io.*;import java.util.*;import org.json.simple.*;import org.json.simple.parser.JSONParser;
import core.game.node.entity.player.Player;import core.game.world.map.Location;import core.game.interaction.MovementPulse;import core.net.packet.in.Packet;import core.net.packet.PacketProcessor;
public class Support{
 static Map input;static Player player;static List<Object>events;static Map<String,Integer>calls;public static List<MovementPulse>pulses;
 public static class Failure extends RuntimeException{}
 static int n(Object v){return((Number)v).intValue();}static int v(Map m,String k,int d){return m.get(k)==null?d:n(m.get(k));}static boolean b(Map m,String k){return Boolean.TRUE.equals(m.get(k));}
 static Location loc(Object o){if(o==null)return null;List a=(List)o;return Location.create(n(a.get(0)),n(a.get(1)),n(a.get(2)));}
 public static Object coord(Location l){return l==null?null:Arrays.asList(l.getX(),l.getY(),l.getZ());}
 public static boolean answer(String key){return !Boolean.FALSE.equals(input.get(key));}
 public static void emit(String name,Object...args){List<Object> row=new ArrayList<>();row.add(name);row.addAll(Arrays.asList(args));events.add(row);int count=calls.merge(name,1,Integer::sum);for(Object h:(List)input.getOrDefault("hooks",Collections.emptyList())){Map hook=(Map)h;if(name.equals(hook.get("event"))&&count==v(hook,"at",1))for(Object a:(List)hook.get("actions"))act((Map)a);}}
 static void set(Map m){if(m.containsKey("location"))player.location=loc(m.get("location"));if(m.containsKey("locked"))player.locked=b(m,"locked");if(m.containsKey("opened"))player.opened=b(m,"opened");if(m.containsKey("chatbox"))player.chatbox=b(m,"chatbox");if(m.containsKey("openWalkable"))player.openWalkable=(Boolean)m.get("openWalkable");if(m.containsKey("chatWalkable"))player.chatWalkable=(Boolean)m.get("chatWalkable");if(m.containsKey("running"))player.running=b(m,"running");for(String key:new String[]{"close","dialogue","maxDistance"})if(m.containsKey(key))input.put(key,m.get(key));core.ServerConstants.MAX_PATHFIND_DISTANCE=v(input,"maxDistance",25);}
 static Object act(Map a){switch((String)a.get("op")){case"fail":throw new Failure();case"set":set(a);return null;case"arrival":return pulses.get(v(a,"index",pulses.size()-1)).pulse();case"process":{
  Player p=input.containsKey("player")&&input.get("player")==null?null:player;int x=v(a,"x",3210),y=v(a,"y",3216);boolean r=b(a,"running");Packet pkt;switch((String)a.getOrDefault("kind","world")){case"world":{Packet.WorldspaceWalk q=new Packet.WorldspaceWalk();q.player=p;q.destX=x;q.destY=y;q.isRun=r;pkt=q;break;}case"interact":{Packet.InteractWalk q=new Packet.InteractWalk();q.player=p;q.destX=x;q.destY=y;q.isRun=r;pkt=q;break;}case"minimap":{Packet.MinimapWalk q=new Packet.MinimapWalk();q.player=p;q.destX=x;q.destY=y;q.isRun=r;pkt=q;break;}default:pkt=new Packet();}PacketProcessor.handle(pkt);return null;}default:throw new IllegalArgumentException();}}
 static Object snapshot(Object result,String error){Map<String,Object>m=new TreeMap<>();m.put("location",coord(player.location));m.put("running",player.running);m.put("events",new ArrayList<>(events));m.put("result",result);m.put("error",error);List<Object>ps=new ArrayList<>();for(MovementPulse p:pulses)ps.add(Arrays.asList(coord(p.location),p.force));m.put("pulses",ps);m.put("maxDistance",core.ServerConstants.MAX_PATHFIND_DISTANCE);return m;}
 public static void main(String[]args)throws Exception{try(BufferedReader r=new BufferedReader(new InputStreamReader(System.in,java.nio.charset.StandardCharsets.UTF_8))){String line;while((line=r.readLine())!=null){input=(Map)new JSONParser().parse(line);Map initial=new TreeMap(input);events=new ArrayList<>();calls=new HashMap<>();pulses=new ArrayList<>();player=new Player();player.location=loc(input.getOrDefault("location",Arrays.asList(3207L,3216L,0L)));set(input);List<Object>states=new ArrayList<>();for(Object o:(List)input.get("actions")){events.clear();Object result=null;String error=null;try{result=act((Map)o);}catch(Failure e){error="Binding";}catch(NullPointerException e){error="Null";}catch(IndexOutOfBoundsException e){error="Index";}states.add(snapshot(result,error));}initial.put("expected",states);System.out.println(JSONValue.toJSONString(initial));}}}
}
